package br.com.cineo;
import android.graphics.*;import android.graphics.drawable.*;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import static br.com.cineo.MainActivity.*;
/** Private-storage artwork loaded through the authenticated API, with stable disk cache and visible retry. */
class Artwork {
 final MainActivity a;final ConcurrentHashMap<String,Object> locks=new ConcurrentHashMap<>();Artwork(MainActivity activity){a=activity;}
 FrameLayout poster(JSONObject show,int height,boolean banner){FrameLayout frame=new FrameLayout(a);GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff3a2238,0xff172f40});gradient.setCornerRadius(a.dp(12));frame.setBackground(gradient);frame.setClipToOutline(true);frame.setMinimumHeight(a.dp(height));ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));TextView state=a.label("",12,MUTED);state.setGravity(Gravity.CENTER);state.setPadding(a.dp(12),a.dp(12),a.dp(12),a.dp(12));frame.addView(state,new FrameLayout.LayoutParams(-1,-1));String resource=show.optString(banner?"banner_url":"cover_url");if(resource.isEmpty())resource=show.optString("cover_url");if(resource.startsWith("android.resource://")){a.image(image,resource);state.setVisibility(View.GONE);return frame;}String path=banner&&!show.optString("banner_path").isEmpty()?show.optString("banner_path"):show.optString("cover_path");if(path.isEmpty()&&resource.isEmpty()){state.setText("Cartaz em preparação");return frame;}String key=show.optInt("id")+":"+path;final String url=resource;final boolean large=height>=300;Runnable load=()->load(show.optInt("id"),banner,key,url,large,image,state);state.setOnClickListener(v->load.run());Bitmap cached=a.cache.get("art9:"+a.fastCache.scope()+key+large);if(cached!=null){image.setImageBitmap(cached);state.setVisibility(View.GONE);return frame;}final ViewTreeObserver.OnPreDrawListener[] observer={null};observer[0]=()->{Rect rect=new Rect();if(image.isShown()&&image.getGlobalVisibleRect(rect)&&rect.height()>0){if(frame.getViewTreeObserver().isAlive())frame.getViewTreeObserver().removeOnPreDrawListener(observer[0]);load.run();}return true;};frame.getViewTreeObserver().addOnPreDrawListener(observer[0]);frame.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){if(frame.getViewTreeObserver().isAlive())frame.getViewTreeObserver().removeOnPreDrawListener(observer[0]);}});return frame;}
 byte[] download(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);try{int code=c.getResponseCode();if(code==401||code==403||code==404)throw new FileNotFoundException("Endereço expirado.");if(code!=200)throw new IOException("Imagem indisponível.");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>2097152)throw new IOException("Imagem muito grande.");}return out.toByteArray();}}finally{c.disconnect();}}
 Bitmap decode(byte[] bytes,boolean large){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);BitmapFactory.Options options=new BitmapFactory.Options();int target=large?1400:600;while(bounds.outWidth/Math.max(1,options.inSampleSize)>target||bounds.outHeight/Math.max(1,options.inSampleSize)>target)options.inSampleSize=options.inSampleSize==0?2:options.inSampleSize*2;return BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);}
 void load(int id,boolean banner,String key,String url,boolean large,ImageView target,TextView state){final String account=a.uid,viewer=a.viewerToken,scope=a.fastCache.scope(),tag=scope+key+large;target.setTag(tag);Bitmap cached=a.cache.get("art9:"+tag);if(cached!=null){target.setImageBitmap(cached);state.setVisibility(View.GONE);return;}state.setText("Preparando imagem…");a.images.execute(()->{try{File file=new File(a.getCacheDir(),"art9-"+a.fastCache.hash(scope+key)+".jpg");byte[] bytes;Object lock=locks.computeIfAbsent(file.getName(),k->new Object());synchronized(lock){if(file.isFile())bytes=java.nio.file.Files.readAllBytes(file.toPath());else{File legacy=new File(a.getCacheDir(),"art-"+android.util.Base64.encodeToString(key.getBytes(java.nio.charset.StandardCharsets.UTF_8),11)+".jpg");if(legacy.isFile()&&legacy.length()<=2097152)bytes=java.nio.file.Files.readAllBytes(legacy.toPath());else{bytes=null;if(url.startsWith("https://"))try{bytes=download(url);}catch(FileNotFoundException expired){}if(bytes==null){a.requestViewer.set(viewer);a.readFlow.ensureSession(account);JSONObject r=a.request("GET","/v6/art/"+id+"?kind="+(banner?"banner":"cover"),null,a.token);bytes=android.util.Base64.decode(r.getString("image"),2);}}BitmapFactory.Options validation=new BitmapFactory.Options();validation.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,validation);if(validation.outWidth<=0||validation.outHeight<=0)throw new IOException("Imagem inválida");File temp=new File(file+".part");try(FileOutputStream out=new FileOutputStream(temp)){out.write(bytes);}if(!temp.renameTo(file))temp.delete();}}locks.remove(file.getName(),lock);final Bitmap bitmap=decode(bytes,large);if(bitmap==null){file.delete();throw new IOException("Imagem incompleta");}a.cache.put("art9:"+tag,bitmap);a.runOnUiThread(()->{if(!tag.equals(target.getTag())||!account.equals(a.uid)||!viewer.equals(a.viewerToken))return;target.setImageBitmap(bitmap);target.setAlpha(1f);state.setVisibility(View.GONE);});prune();}catch(Exception ex){a.runOnUiThread(()->{if(!tag.equals(target.getTag()))return;state.setText("Imagem indisponível\nToque para tentar novamente");state.setVisibility(View.VISIBLE);});}finally{a.requestViewer.remove();}});}
 void prune(){File[] files=a.getCacheDir().listFiles((d,n)->n.startsWith("art9-")&&n.endsWith(".jpg"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());long bytes=0;for(int i=0;i<files.length;i++){bytes+=files[i].length();if(i>=80||bytes>32000000)files[i].delete();}}
}
